export function LeadCaptureForm({
  heading = "{{heading}}",
  submitText = "{{submitText}}",
  fieldSet = "{{fieldSet}}",
  accent = "{{accent}}",
}) {
  return (
    <form style={{ font: "15px system-ui, sans-serif", color: "#241430", display: "flex", flexDirection: "column",
      gap: 8, maxWidth: 320, padding: 22, border: "1px solid #24143022", borderRadius: 14, background: "#FAF7F2" }}>
      <h2 style={{ margin: "0 0 8px", fontSize: 19, fontWeight: 700 }}>{heading}</h2>
      <label htmlFor="lead-name" style={{ fontSize: 13, fontWeight: 600 }}>Name</label>
      <input id="lead-name" type="text" name="name" required style={{ font: "inherit", padding: "9px 11px", border: "1px solid #24143033", borderRadius: 8 }} />
      <label htmlFor="lead-email" style={{ fontSize: 13, fontWeight: 600 }}>Work email</label>
      <input id="lead-email" type="email" name="email" required style={{ font: "inherit", padding: "9px 11px", border: "1px solid #24143033", borderRadius: 8 }} />
      {fieldSet === "detailed" && (
        <>
          <label htmlFor="lead-company" style={{ fontSize: 13, fontWeight: 600 }}>Company</label>
          <input id="lead-company" type="text" name="company" style={{ font: "inherit", padding: "9px 11px", border: "1px solid #24143033", borderRadius: 8 }} />
        </>
      )}
      <button type="submit" style={{ marginTop: 10, border: "none", color: "#FAF7F2", padding: 11, borderRadius: 8,
        fontWeight: 700, cursor: "pointer", background: accent }}>{submitText}</button>
    </form>
  );
}
